INSERT INTO `tbl_about` (`id`, `title`, `short_description`, `description`, `imgname`) VALUES
(1, 'WE ARE A COMMUNITY MORE THAN A CONSULTANCY', 'WE ARE A FIRST OF A KIND IN WHAT WE DO! ', '<p class=\"15\" style=\"margin-left:21.0000pt;mso-para-margin-left:0.0000gd;text-indent:-21.0000pt;\r\nmso-char-indent-count:0.0000;mso-list:l0 level1 lfo1;\"></p><ul><li><span style=\"font-family: Calibri; font-size: 11pt; text-indent: -21pt;\">First to provide scholarships to deserving Indian students in our community.</span></li><li><span style=\"font-family: Calibri; font-size: 11pt; text-indent: -21pt;\">First to run a student support service from the UK for over 12 years.</span></li><li><span style=\"font-family: Calibri; font-size: 11pt; text-indent: -21pt;\">First to offer one-on-one counselling by professionals.</span></li><li><span style=\"font-family: Calibri; font-size: 11pt; text-indent: -21pt;\">First to care for your well-being in the UK through small gatherings and activities.</span></li><li><span style=\"font-family: Calibri; font-size: 11pt; text-indent: -21pt;\">First to organize networking events for students to learn from professionals, professors, and alumni.</span></li></ul><!--[if !supportLists]--><p></p>', '240209050222_WhatsApp_Image_2024-02-06_at_12.20.10_PM_(4).jpeg.jpg');
