INSERT INTO `tbl_appointment_link` (`id`, `link`, `description`) VALUES
(1, '-uxNWWXg_00', '<div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">1. Personalized career counselling with Mr. Vijay and networking with industry professionals in the UK. ( Your parents are welcome! )</span></div><div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">2. Comprehensive support throughout the entire admission and visa application process.</span></div><div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">3. Assistance in finding accommodations and guidance on securing education loans.</span></div><div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">4. BMGC Scholarships available for deserving candidates.</span></div><div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">5. Access to the BMGC community/network in the UK for ongoing support.</span></div><div><span style=\"font-family: Calibri; font-size: 14.6667px; font-weight: 700;\">6. After landing support, including mental health well-being and participation in BMGC events for Tamil students.</span></div>');
