(1, 'Christmas markets 2023', '240207030233_WhatsApp_Image_2024-02-06_at_12.20.11_PM.jpeg.jpg', NULL, 'Christmas markets in Manchester', '1', '2024-02-02 14:29:31', '1', '2024-02-07 15:33:43', 'NDL', '1', '2024-02-03 14:54:59'),
(2, 'New year celebration 2024', '240207030232_WhatsApp_Image_2024-02-06_at_12.20.11_PM_(1).jpeg.jpg', NULL, 'Celebrating the new year with students in Allendale, Northumberland, must have been a great way to build community spirit and welcome the start of 2024 together!', '1', '2024-02-02 14:30:12', '1', '2024-02-07 15:32:26', 'NDL', NULL, NULL),
(3, 'Pongal Celebration at Vijay house', '240207030230_WhatsApp_Image_2024-02-06_at_12.20.11_PM_(3)_comp_(1).jpeg.jpg', NULL, 'Celebrating Pongal with students away from home helps them stay connected to Tamil culture and family traditions. It fosters a sense of community and belonging while ensuring they don^t miss out on festivities.', '1', '2024-02-02 14:30:24', '1', '2024-02-07 15:31:40', 'NDL', NULL, NULL),
(4, 'BMGC Connect - 2023 ', '240207030234_bmgc_print_(1)_jpg_(1).jpg', NULL, 'First of a kind event in the UK for our Tamilnadu students. We had around 250 people including students, professionals and recent graduates who secured their jobs in the UK.', '1', '2024-02-07 15:36:48', NULL, NULL, 'NDL', NULL, NULL),
(5, 'Edinburgh Trip 2024', '240209020253_WhatsApp_Image_2024-02-06_at_12.20.11_PM_(2).jpeg.jpg', NULL, '', '1', '2024-02-09 02:53:13', NULL, NULL, 'NDL', NULL, NULL),
(6, 'After event selfie - 2023', '240209020254_WhatsApp_Image_2024-02-06_at_12.20.10_PM_(4).jpeg.jpg', NULL, 'Look at all our tired faces', '1', '2024-02-09 02:54:52', NULL, NULL, 'NDL', NULL, NULL),
(7, 'The team behind 2023 event', '240209020255_WhatsApp_Image_2024-02-06_at_12.20.10_PM_(2).jpeg.jpg', NULL, '', '1', '2024-02-09 02:55:28', NULL, NULL, 'NDL', NULL, NULL),
(8, 'Birmingham Students meet up 2023', '240209020255_WhatsApp_Image_2024-02-06_at_12.20.10_PM_(3).jpeg.jpg', NULL, '', '1', '2024-02-09 02:56:27', NULL, NULL, 'NDL', NULL, NULL),
(9, 'Even prep meeting 2023 Birmingham', '240209020256_WhatsApp_Image_2024-02-06_at_12.20.09_PM_(5).jpeg.jpg', NULL, '', '1', '2024-02-09 02:57:32', NULL, NULL, 'NDL', NULL, NULL),
(10, 'Trekking with the core team 2023', '240209020257_WhatsApp_Image_2024-02-06_at_12.20.10_PM_comp.jpeg.jpg', NULL, 'Snowdonia Trek!', '1', '2024-02-09 02:58:07', NULL, NULL, 'NDL', NULL, NULL),
(11, 'Chennai meetup 2023', '240209020258_WhatsApp_Image_2024-02-06_at_12.20.09_PM_(3).jpeg.jpg', NULL, 'We been kicked out of the food court in a mall :D', '1', '2024-02-09 02:59:04', NULL, NULL, 'NDL', NULL, NULL),
(12, 'Madurai meetup 2023', '240209020259_WhatsApp_Image_2024-02-06_at_12.20.09_PM_(1).jpeg.jpg', NULL, 'Puppy^s bakery :)', '1', '2024-02-09 03:00:16', NULL, NULL, 'NDL', NULL, NULL),
