(16, 'London Trip 2023', '240209030202_WhatsApp_Image_2024-02-06_at_12.20.08_PM_(3).jpeg.jpg', NULL, 'Expensive trip ever!', '1', '2024-02-09 03:02:50', NULL, NULL, 'NDL', NULL, NULL),
(17, 'New year celebration 2023', '240209030203_WhatsApp_Image_2024-02-06_at_12.20.08_PM_(2).jpeg.jpg', NULL, 'A trip to Scotland during winter, including tackling the challenging NC500 route in snow, was an amazing time we had to foster stronger relationships.', '1', '2024-02-09 03:04:02', NULL, NULL, 'NDL', NULL, NULL),
(18, 'Christmas markets 2022 ', '240209030204_WhatsApp_Image_2024-02-06_at_12.20.08_PM_(1).jpeg.jpg', NULL, '', '1', '2024-02-09 03:04:27', NULL, NULL, 'NDL', NULL, NULL),
