INSERT INTO `tbl_process` (`ban_id`, `title`, `imgname`, `order_no`, `description`, `created_by`, `create_date`, `updated_by`, `update_date`, `delete_status`, `deleted_by`, `deleted_date`) VALUES
(1, 'We Ask ', '240203030227_featured-image-17_(1).jpg', NULL, 'Firstly we and yourself should be clear on what your plan, idea and end goal is via a 30 minute free online conversation. So we ask. â€“ Change this to â€“ Firstly we and you should be clear on what your plan, idea and end goal is via a 30-45 minute video counselling session (Do not miss to bring your CV & feel free to welcome your parents to the meeting) So, we ask.', '1', '2024-02-03 15:27:31', NULL, NULL, 'NDL', NULL, NULL),
(2, 'We listen', '240203030227_featured-image-8.jpg', NULL, 'Secondly we should write a map that will help you succeed so we draft your educational and financial backdrop, experiences and career ideas. So we listen.', '1', '2024-02-03 15:27:46', NULL, NULL, 'NDL', NULL, NULL),
(3, 'We analyse ', '240203030227_featured-image-16.jpg', NULL, 'There are set rules and guidelines in every country that we have to fulfil in order to convert your plan, idea and end goal into reality. We analyse your idea, plan and goal based on all your factors to find the best country, course, finance and university. So we analyse.', '1', '2024-02-03 15:28:02', NULL, NULL, 'NDL', NULL, NULL),
(4, 'We suggest', '240203030228_featured-image-5.jpg', NULL, 'Not every person is born with a silver spoon, we differ in certain aspects, yet we all are one. So we personally tailor the route map to success based on a personalised analysis of each and every aspect of you and advise on the ideal university, country and course, possible financial supports, scholarships available, educational system of the country, the intake polices and every other aspect that suits your passion and dream.So we suggest.', '1', '2024-02-03 15:28:20', NULL, NULL, 'NDL', NULL, NULL),
(5, 'We process', '240203030228_featured-image-13.jpg', NULL, 'Finally, we guide you throughout the detailed application and requisite procedures. Including document advice, suggestions, ideas and reviews on statement of purpose(SOP), suggestions on offer acceptance, processing Visa applications, ticketing, boarding and landing, and finding the best affordable accommodation and hence forth.And we process.', '1', '2024-02-03 15:28:35', NULL, NULL, 'NDL', NULL, NULL);
INSERT INTO `tbl_service` (`service_id`, `title`, `imgname`, `order_no`, `description`, `created_by`, `create_date`, `updated_by`, `update_date`, `delete_status`, `deleted_by`, `deleted_date`) VALUES
(1, 'One-to-One Career Counselling Session', '', NULL, 'You will have the opportunity to engage in a personalized career counselling session with Mr. Vijay. If necessary, he can also connect you with current professionals from your industry in the UK.', '1', '2024-02-05 15:31:27', '1', '2024-02-06 14:57:31', 'NDL', NULL, NULL),
(2, 'Complete Admission Process Support', '', NULL, 'We will guide you through the entire admission process, from shortlisting the best universities to assisting with the application process and navigating the sometimes complex Visa application.', '1', '2024-02-05 15:31:39', '1', '2024-02-07 12:49:30', 'NDL', NULL, NULL),
(3, 'Assistance with Accommodations and Education Loans', '', NULL, 'We\'ll help you find suitable accommodations and provide guidance on securing education loans if needed.', '1', '2024-02-05 15:31:55', '1', '2024-02-07 12:49:01', 'NDL', NULL, NULL),
(4, 'BMGC Scholarships', '', NULL, 'The BMGC is delighted to offer scholarships for deserving candidates! Pursue your educational aspirations with financial support from us.', '1', '2024-02-05 15:32:05', '1', '2024-02-06 15:01:36', 'NDL', NULL, NULL),
(5, 'Access to Our BMGC Community/Network in the UK', '', NULL, 'We will connect you with our BMGC community in the UK, ensuring you have a support network throughout your study abroad journey.', '1', '2024-02-05 15:32:14', '1', '2024-02-07 12:50:06', 'NDL', NULL, NULL),
(6, 'After Landing Support', '', NULL, 'We never leave you alone after you come to the UK as other agencies/consultancies do. Our community is there to attend to you if you require any sort of support including mental health well-being etc. and make sure you participate in any quick meets or events organized by BMGC for our Tamil students.', '1', '2024-02-05 15:32:24', '1', '2024-02-07 12:49:55', 'NDL', NULL, NULL),
(7, 'Condition', '', NULL, 'We help students to come to the UK through BMGC only if they^re career-oriented and wish to help upcoming fellow students from Tamilnadu to encourage and motivate them.Â ', '1', '2024-02-06 14:19:05', '1', '2024-02-06 14:21:30', '0', '1', '2024-02-06 15:11:26');
INSERT INTO `tbl_services` (`id`, `title`, `short_description`, `description`) VALUES
(1, 'Services', 'Our comprehensive set of services to make your transition as smooth as possible', '<p class=\"15\" style=\"margin-left:21.0000pt;mso-para-margin-left:0.0000gd;text-indent:-21.0000pt;\r\nmso-char-indent-count:0.0000;mso-list:l0 level1 lfo1;\"></p><ul><li><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">1.&nbsp;One-to-One Career Counselling Session:</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">&nbsp;You will have the opportunity to engage in a personalized career counselling session with Mr. Vijay. If necessary, he can also connect you with current professionals from your industry in the UK.&nbsp;&nbsp;&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">2.&nbsp;Complete Admission Process Support:</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">&nbsp;We will guide you through the entire admission process, from shortlisting the best universities to&nbsp;assisting&nbsp;with the application process and navigating the&nbsp;sometimes complex&nbsp;Visa application.&nbsp;&nbsp;&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">3.&nbsp;Assistance&nbsp;with Accommodations and Education Loans:</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">&nbsp;We^ll&nbsp;help you find suitable accommodations and&nbsp;provide&nbsp;guidance on securing education loans if needed.&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">4.&nbsp;BMGC Scholarships</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">:&nbsp;The BMGC is delighted to offer scholarships for deserving candidates! Pursue your educational aspirations with financial support from us.&nbsp;&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">5.&nbsp;Access to Our BMGC Community/Network in the UK:</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">&nbsp;We will connect you with our BMGC community in the UK, ensuring you have a support network throughout your study abroad journey.&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-indent:36.0000pt;\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">6. &nbsp;After Landing Support:</span></b><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\">&nbsp;We never leave you alone after you come to the UK as other agencies/consultancies do. Our community is there to attend to you if you require any sort of support including mental health well-being etc and make sure you participate in any quick meets or events organised by BMGC for our Tamil students.&nbsp;</span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><br></span><span style=\"mso-spacerun:^yes^;font-family:Calibri;mso-bidi-font-family:^Times New Roman^;\r\nfont-size:11.0000pt;mso-font-kerning:1.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\"><b><span style=\"font-family: Calibri; font-size: 11pt;\">Condition: We help students to come to the UK through BMGC only if they^re career-oriented and wish to help upcoming fellow students from Tamilnadu to encourage and motivate them.&nbsp;</span></b></p></li></ul><!--[if !supportLists]--><p></p>');
